-- Verified SAT Valley September 2026 practice-set intake, 21 of 24.
-- Source is the user's Library attachment; its checksum and page are retained.
-- Preserves all prior questions, keys, attempts, and student data.
begin;
set local statement_timeout='45s';
create temporary table sat_sep_intake on commit drop as
 select * from jsonb_to_recordset('[{"n":1,"page":1,"topic":"Right triangles and trigonometry","lesson":"Right triangles and trigonometry","idea":"Inscribed rectangle and 30–60–90 triangle","difficulty":"hard","stem":"A rectangle is inscribed in a circle. Its diagonal is twice its shorter side. The area of the circle is $5,929\\pi$. What is the area of the rectangle?","choices":["$77\\sqrt2$","$77\\sqrt3$","$5,929\\sqrt2$","$5,929\\sqrt3$"],"correct":"D","explanation":"The radius is 77, so the diameter and rectangle diagonal are 154. The shorter side is 77 and the other side is $\\sqrt{154^2-77^2}=77\\sqrt3$. The area is $5,929\\sqrt3$.","id":"c1f542e6-3a40-5aaf-ba79-00d01d42a9cc","code":"SATVALLEY-SEP26-Q01","focus":"must_know","takeaway":"The radius is 77, so the diameter and rectangle diagonal are 154."},{"n":2,"page":2,"topic":"Percentages","lesson":"Percentages","idea":"Chained percentages and units","difficulty":"hard","stem":"The speed of K is 9,525% of the speed of J, and K is 0.025% of the speed of L. If the speed of L is x% of that of J, what is x/1,000?","choices":[],"correct":"38100","explanation":"K = 95.25J and K = 0.00025L. Hence L = 381,000J, so x = 38,100,000 and x/1,000 = 38,100.","id":"786a8b36-680e-5cdc-a480-dedc1cdf1969","code":"SATVALLEY-SEP26-Q02","focus":"unique","takeaway":"K = 95."},{"n":3,"page":3,"topic":"Exponential functions","lesson":"Exponential models","idea":"Rewriting growth by interval","difficulty":"medium","stem":"Every increase of $1/2$ in x multiplies f(x) by c. Which equivalent form shows c as its base?","choices":["$56(2)^{6x}$","$56(8)^{2x}$","$56(64)^x$","$56(4096)^{x/2}$"],"correct":"B","explanation":"All forms equal $56(64)^x$. Increasing x by $1/2$ multiplies the value by $64^{1/2}=8$. Choice B shows 8 as the base.","id":"b5f143f9-9671-561d-920f-7760e4e702b5","code":"SATVALLEY-SEP26-Q03","focus":"must_know","takeaway":"All forms equal $56(64)^x$."},{"n":4,"page":4,"topic":"Systems of two linear equations in two variables","lesson":"Linear systems","idea":"Parametrizing infinitely many solutions","difficulty":"medium","stem":"The system $9x+5y=7$ and $45x+25y=35$ represents one line. For every real r, which point satisfies both equations?","choices":["$(r/5+7, -r/5+35)$","$(-5r/9+7/9,r)$","$(r,9r/5+7/5)$","$(r,-5r/9+7/9)$"],"correct":"B","explanation":"The second equation is five times the first. Set y=r in $9x+5y=7$ to obtain $x=(7-5r)/9$.","id":"e8b34d86-fb9c-5e73-9ccc-e8674e6890f7","code":"SATVALLEY-SEP26-Q04","focus":"unique","takeaway":"The second equation is five times the first."},{"n":5,"page":5,"topic":"Lines, angles, and triangles","lesson":"Angles, triangles and similarity","idea":"AAS congruence versus ambiguous SSA","difficulty":"hard","stem":"In triangles ABC and DEF, BC = EF = 23 inches and angles C and F are both 43°. Which additional facts are sufficient to prove the triangles congruent? I: angles D and E are equal. II: AB = DE. III: angles A and D are equal.","choices":["I only","II only","II and III only","III only"],"correct":"D","explanation":"III gives a second corresponding angle. Two matching angles and the matching side BC = EF establish congruence by AAS. II alone is SSA, which can be ambiguous; I concerns only triangle DEF.","id":"dd54b3d7-d7fb-5b9a-b35a-154d0a6b4ae2","code":"SATVALLEY-SEP26-Q05","focus":"must_know","takeaway":"III gives a second corresponding angle."},{"n":6,"page":6,"topic":"Percentages","lesson":"Percentages","idea":"Mixture concentration equation","difficulty":"medium","stem":"How many liters of 30% chlorine solution should be added to 12 liters of 10% solution to obtain 15% solution?","choices":[],"correct":"4","explanation":"Let x be the added liters. Equate chlorine: $0.30x+0.10(12)=0.15(x+12)$. Then $0.15x=0.6$ and x=4.","id":"9a234ca0-c071-5bac-9cff-9f6b5dc7b924","code":"SATVALLEY-SEP26-Q06","focus":"must_know","takeaway":"Let x be the added liters."},{"n":7,"page":7,"topic":"Quadratic functions","lesson":"Quadratics","idea":"Revenue as a quadratic","difficulty":"hard","stem":"At a price of 120 dollars, no products are sold. For each additional product sold, the price falls by 2.50 dollars. If revenue is 1,440 dollars, how many products are sold?","choices":[],"correct":"24","explanation":"For n products, price is $120-2.5n$ and revenue is $n(120-2.5n)$. Setting this to 1,440 gives $(n-24)^2=0$, so n=24.","id":"717681d6-d39b-55e4-9c68-13b88d15ee38","code":"SATVALLEY-SEP26-Q07","focus":"must_know","takeaway":"For n products, price is $120-2."},{"n":8,"page":8,"topic":"Linear inequalities in one or two variables","lesson":"Linear inequalities","idea":"Consecutive odd integers and inequalities","difficulty":"hard","stem":"Three consecutive odd integers, ordered from least to greatest, start at k. Seventeen times the second is at most 40 less than the sum of the first and third. What is the greatest possible k?","choices":[],"correct":"-5","explanation":"The integers are k, k+2 and k+4. $17(k+2)\\le 2k+4-40$ implies $15k\\le-70$, hence $k\\le-14/3$. The greatest odd integer is −5.","id":"0598d845-b052-5df2-aea9-49e0e03ca383","code":"SATVALLEY-SEP26-Q08","focus":"unique","takeaway":"The integers are k, k+2 and k+4."},{"n":9,"page":9,"topic":"Right triangles and trigonometry","lesson":"Right triangles and trigonometry","idea":"Coterminal radians on a unit circle","difficulty":"hard","stem":"Starting at (1,0) on the unit circle, rotate counterclockwise by $478\\pi/3$ radians to reach point J=(a,b). What is b?","choices":["$-1/2$","$-\\sqrt3/2$","$1/2$","$\\sqrt3/2$"],"correct":"B","explanation":"Subtract whole turns: $478\\pi/3$ is coterminal with $4\\pi/3$. Thus $b=\\sin(4\\pi/3)=-\\sqrt3/2$.","id":"53c41dd0-3625-5432-a1de-88101bbe4f80","code":"SATVALLEY-SEP26-Q09","focus":"must_know","takeaway":"Subtract whole turns: $478\\pi/3$ is coterminal with $4\\pi/3$."},{"n":10,"page":10,"topic":"One-variable data: distributions and measures of center and spread","lesson":"Statistics","idea":"Removing extremes changes mean and spread","difficulty":"hard","stem":"A data set of 37 different values has minimum 230, maximum 278, mean 244 and standard deviation 9. Remove 230 and 278. What happens to the mean and standard deviation?","choices":["Both decrease","Both increase","Standard deviation decreases; mean stays the same","Standard deviation increases; mean stays the same"],"correct":"A","explanation":"The removed pair averages 254, above 244, so the new mean is $(37·244-230-278)/35=243.4286$. Their squared deviations from 244 total 1,352; recalculating spread about the new mean gives a smaller SD under either population or sample convention.","id":"2244a08a-2337-584d-aa09-dd1f6b14aaeb","code":"SATVALLEY-SEP26-Q10","focus":"must_know","takeaway":"The removed pair averages 254, above 244, so the new mean is $(37·244-230-278)/35=243."},{"n":11,"page":11,"topic":"Nonlinear functions","lesson":"Functions and graphs","idea":"Square-root endpoint and sign","difficulty":"medium","stem":"$g(x)=a\\sqrt{b-x}$ passes through (36,0) and $g(16)<0$. Which must hold?","choices":["a>0","b<0","a<b","g(0)=36"],"correct":"C","explanation":"Since $g(16)<0$, a is negative and nonzero. $g(36)=0$ then forces b=36, so a<b.","id":"f5d0e4dd-b96f-5105-ab1f-f6f3aad452b8","code":"SATVALLEY-SEP26-Q11","focus":"must_know","takeaway":"Since $g(16)<0$, a is negative and nonzero."},{"n":12,"page":12,"topic":"Area and volume","lesson":"Area and volume","idea":"Pyramid slant height and surface area","difficulty":"hard","stem":"Two right square pyramids have the same base area of 400 square inches and heights 13 and 39 inches. What is the difference between their surface areas, rounded to the nearest square inch?","choices":[],"correct":"954","explanation":"The base side is 20, so each slant height is $\\sqrt{h^2+10^2}$. The base areas cancel. Difference $=40(\\sqrt{1621}-\\sqrt{269})\\approx954.4$, rounding to 954.","id":"f9ff3cda-a181-511c-9c4d-d5535befc39f","code":"SATVALLEY-SEP26-Q12","focus":"must_know","takeaway":"The base side is 20, so each slant height is $\\sqrt{h^2+10^2}$."},{"n":13,"page":13,"topic":"Ratios, rates, proportional relationships, and units","lesson":"Ratios, rates and units","idea":"Shared ratio with two group totals","difficulty":"hard","stem":"Ranches A and B have 168 and 344 horses. Across both ranches the male:female ratio is 1:15, and female horses on A:B are in ratio 7:17. How many more male horses are on A than on B?","choices":[],"correct":"24","explanation":"There are 512 horses: 32 males and 480 females. Females on A and B are 140 and 340, giving males 168−140=28 and 344−340=4. Difference is 24.","id":"b4eb1482-0320-505e-9ab5-93db23e79197","code":"SATVALLEY-SEP26-Q13","focus":"unique","takeaway":"There are 512 horses: 32 males and 480 females."},{"n":14,"page":14,"topic":"Equivalent expressions","lesson":"Polynomials","idea":"Factor theorem with an integer parameter","difficulty":"hard","stem":"For which polynomial is $x+3k$ a factor for some positive integer k?","choices":["$4x^2+9x+27k$","$4x^2+15x+27k$","$4x^2+27x+27k$","$4x^2+45x+27k$"],"correct":"D","explanation":"Set x=−3k in $4x^2+Bx+27k$: $3k(12k-B+9)=0$, so B=12k+9. Only B=45 gives positive integer k=3.","id":"e8e5ea6b-1156-5838-a912-03d320cbc039","code":"SATVALLEY-SEP26-Q14","focus":"must_know","takeaway":"Set x=−3k in $4x^2+Bx+27k$: $3k(12k-B+9)=0$, so B=12k+9."},{"n":15,"page":15,"topic":"Lines, angles, and triangles","lesson":"Angles, triangles and similarity","idea":"Supplementary acute and obtuse angles","difficulty":"medium","stem":"A transversal of parallel lines makes obtuse angles of measure $(−6x+380)°$. The sum of two acute angles and one obtuse angle is $(ax-k)°$ for positive constants a and k. Find a+k.","choices":[],"correct":"26","explanation":"Each acute angle is $180-(−6x+380)=6x-200$. Thus twice acute plus one obtuse is $6x-20$, so a=6, k=20 and a+k=26.","id":"e712ea33-f2eb-5300-b8d1-df655e50be01","code":"SATVALLEY-SEP26-Q15","focus":"unique","takeaway":"Each acute angle is $180-(−6x+380)=6x-200$."},{"n":16,"page":16,"topic":"Quadratic equations","lesson":"Quadratics","idea":"Discriminant after clearing rational denominators","difficulty":"hard","stem":"For integer k, the equation $1/k+x/118=1/(kx)$ has no real solution. What is the greatest possible k? (The equation requires k≠0 and x≠0.)","choices":[],"correct":"-30","explanation":"Multiply by 118kx to get $kx^2+118x-118=0$. Its discriminant is $118^2+472k$, which is negative when $k<-29.5$. Greatest integer: −30.","id":"6bb6db3b-cb7b-5f5a-bd4a-e9749b43764f","code":"SATVALLEY-SEP26-Q16","focus":"unique","takeaway":"Multiply by 118kx to get $kx^2+118x-118=0$."},{"n":17,"page":17,"topic":"Area and volume","lesson":"Area and volume","idea":"Converting a volume ratio to surface area","difficulty":"hard","stem":"Similar prisms A and B have volumes 4,374 and 1,500,282 cubic inches. Prism A has surface area 1,782 square inches. What is the surface area of B?","choices":["5,346","12,474","87,318","611,226"],"correct":"C","explanation":"The volume ratio is 343=7³, so the side ratio is 7 and the surface-area ratio 7²=49. Hence $1,782·49=87,318$.","id":"74a6464c-f09b-597e-a116-d22d296fd2dc","code":"SATVALLEY-SEP26-Q17","focus":"must_know","takeaway":"The volume ratio is 343=7³, so the side ratio is 7 and the surface-area ratio 7²=49."},{"n":20,"page":20,"topic":"Nonlinear functions","lesson":"Functions and graphs","idea":"Exponential curve versus secant line","difficulty":"hard","stem":"The curve $f(x)=3^x$ intersects an increasing line g at (a,j) and (b,k), with j<k. When is $g(x)>f(x)$?","choices":["x>k","x<j","x<j or x>b","a<x<b"],"correct":"D","explanation":"Because $3^x$ is strictly convex, the secant line through two intersection points is above the curve between them. As j<k, a<b; therefore a<x<b.","id":"e9f2d0d9-d8bf-5ef4-8243-1f82171e6016","code":"SATVALLEY-SEP26-Q20","focus":"must_know","takeaway":"Because $3^x$ is strictly convex, the secant line through two intersection points is above the curve between them."},{"n":21,"page":21,"topic":"Right triangles and trigonometry","lesson":"Right triangles and trigonometry","idea":"Altitude to the hypotenuse in an inscribed triangle","difficulty":"hard","stem":"A, B and C lie on a circle; BC is a diameter of length 82. Triangle ABC is right at A, and altitude AD meets BC at D. If $AD=\\sqrt{592}$ and AC>AB, find CD/BD.","choices":[],"correct":"37/4","explanation":"$BD·CD=AD^2=592$ and $BD+CD=82$, so the two segments are 8 and 74. Since AC>AB, its adjacent hypotenuse segment CD is 74. Thus CD/BD=74/8=37/4.","id":"cc312d17-d26b-5890-ab1d-daff7d404c25","code":"SATVALLEY-SEP26-Q21","focus":"must_know","takeaway":"$BD·CD=AD^2=592$ and $BD+CD=82$, so the two segments are 8 and 74."},{"n":22,"page":22,"topic":"Equivalent expressions","lesson":"Rearranging formulas","idea":"Combining several rational terms","difficulty":"hard","stem":"If $1/c=1/d+1/e+1/f+1/17$ (all denominators nonzero and the right side nonzero), which expression gives c?","choices":["$17def/(d+e+f+17)$","$17def/(17ef+17df+17de+def)$","$(17ef+17df+17de+def)/(17def)$","$d+e+f+17$"],"correct":"B","explanation":"Use the common denominator 17def: $1/c=(17ef+17df+17de+def)/(17def)$, then invert.","id":"72ff5036-42f5-5103-ac0a-2f68ae467fdc","code":"SATVALLEY-SEP26-Q22","focus":"must_know","takeaway":"Use the common denominator 17def: $1/c=(17ef+17df+17de+def)/(17def)$, then invert."},{"n":23,"page":23,"topic":"Nonlinear functions","lesson":"Polynomials","idea":"Sign chart for a cubic","difficulty":"hard","stem":"For distinct constants d,e,f, $g(x)=8(x-d)(x-e)(x-f)$ is positive for every d<x<f. If $g(p)=7>0$, which could be true? I: e<p. II: p<d. III: f<p<e.","choices":["I only","II only","I and II only","I and III only"],"correct":"A","explanation":"Positive throughout (d,f) forces d<f<e. The cubic is positive on (d,f) and (e,∞), so I can hold; II and III put p where g is negative.","id":"141a92df-f79e-5fe2-b0e1-07816d2c1e8c","code":"SATVALLEY-SEP26-Q23","focus":"unique","takeaway":"Positive throughout (d,f) forces d<f<e."}]'::jsonb)
 as x(n integer,page integer,topic text,lesson text,idea text,difficulty text,
      stem text,choices jsonb,correct text,explanation text,id uuid,code text,
      focus text,takeaway text);
do $$ begin
 if (select count(*) from sat_sep_intake) <> 21
   or exists(select 1 from sat_sep_intake group by id having count(*) > 1)
   or exists(select 1 from sat_sep_intake group by code having count(*) > 1)
 then raise exception 'invalid_sat_sep_release'; end if;
 -- Existing IDs may only refer to this identical release (idempotent rerun).
 if exists(select 1 from sat_sep_intake i join public.questions q on q.id=i.id
   left join public.question_keys k on k.question_id=q.id
   where q.track_id <> 'sat' or q.stem <> i.stem
      or q.choices <> (select jsonb_agg(jsonb_build_object('key',chr(64+n::integer),'text',value) order by n)
                      from jsonb_array_elements_text(i.choices) with ordinality c(value,n))
         and jsonb_array_length(i.choices)>0
      or k.correct is distinct from case when jsonb_array_length(i.choices)>0
          then to_jsonb(i.correct) else jsonb_build_array(i.correct) end
      or k.explanation <> i.explanation)
 then raise exception 'sat_sep_existing_row_differs'; end if;
 -- Exact prompt comparison plus stable source ID; near-matches were separately reviewed.
 if exists(select 1 from sat_sep_intake i join public.questions q
   on q.track_id='sat' and q.id<>i.id and (
     q.assets->>'code'=i.code or
     regexp_replace(lower(q.stem),'[^[:alnum:]]','','g')=
     regexp_replace(lower(i.stem),'[^[:alnum:]]','','g')))
 then raise exception 'sat_sep_duplicate_existing_question'; end if;
end $$;
insert into public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
select i.id,'sat',i.topic,i.difficulty,
       case when jsonb_array_length(i.choices)>0 then 'mcq' else 'grid_in' end,
       i.stem,
       coalesce((select jsonb_agg(jsonb_build_object('key',chr(64+n::integer),'text',value) order by n)
                 from jsonb_array_elements_text(i.choices) with ordinality c(value,n)),'[]'::jsonb),
       jsonb_build_object('code',i.code,'paper','SAT Valley September 2026 predictions',
         'source','SAT Valley September 2026 practice set','source_page',i.page,
         'source_number',i.n,'source_sha256','4a9e4676c5588802d579110119ab125bf5980a71bc103a960231722a641d05ee',
         'source_filename','2_5251628363050689570_260910_165338_260927_140341.pdf',
         'source_library_file_id','libfile_ab5b47543a6881919e90749a76c3d5f8',
         'content_review',jsonb_build_object('status','verified',
           'method','Original page read, key independently calculated, options and diagram dependencies checked',
           'source_fidelity','Edited standalone wording; original page retained in supplied Library attachment'))
from sat_sep_intake i on conflict(id) do nothing;
insert into public.question_keys(question_id,correct,explanation)
select i.id,case when jsonb_array_length(i.choices)>0
    then to_jsonb(i.correct) else jsonb_build_array(i.correct) end,i.explanation
from sat_sep_intake i on conflict(question_id) do nothing;
insert into public.revision_items(question_id,lesson,idea,difficulty,programmes,fingerprint,active,focus)
select i.id,i.lesson,i.idea,i.difficulty,array['sat']::text[],
       md5(jsonb_build_array(q.stem,q.choices,q.assets,k.correct,k.explanation)::text),true,
       jsonb_build_object('collections',jsonb_build_array(i.focus),
                          'bank_occurrences',1+(select count(*) from public.revision_items old
                            where old.lesson=i.lesson and old.idea=i.idea and old.question_id<>i.id),
                          'takeaway',i.takeaway)
from sat_sep_intake i join public.questions q on q.id=i.id
join public.question_keys k on k.question_id=q.id
on conflict(question_id) do update set
 lesson=excluded.lesson,idea=excluded.idea,difficulty=excluded.difficulty,
 programmes=excluded.programmes,fingerprint=excluded.fingerprint,
 active=true,focus=excluded.focus;
do $$ begin
 if (select count(*) from public.questions where assets->>'code' like 'SATVALLEY-SEP26-Q%')<>21
   or (select count(*) from sat_sep_intake i join public.question_keys k on k.question_id=i.id)<>21
   or (select count(*) from sat_sep_intake i join public.revision_items r on r.question_id=i.id)<>21
 then raise exception 'sat_sep_release_incomplete'; end if;
end $$;
commit;
